    const first=upperBound(events,from*20+1e-8),last=upperBound(events,to*20+1e-8);
    const shots=[];
    for(let index=first;index<last;index++) {
      const event=events[index];
      if(event.code==="T")shots.push(event);
      else trigger(event);
    }
    while(shotTimes.length&&shotTimes[0]<=elapsed-1)shotTimes.shift();
    shots.sort((a,b)=>shotSound[b.data.type][0]-shotSound[a.data.type][0] || a.index-b.index);
    for(let i=0;i<shots.length&&shotTimes.length<12;i++){
      trigger(shots[i]);shotTimes.push(elapsed);
    }
    if(to>=fallTime+1 && !wind)
      wind=voice({shape:"noise",gain:.033,duration:1,filter:245,filterType:"lowpass",attack:.36,loop:true});
  }

  const byId=id=>document.getElementById(id);
  const countdown=byId("countdown"),toggle=byId("btn-toggle"),scrubber=byId("scrubber");
  const pauseIcon=byId("icon-pause"),playIcon=byId("icon-play");
  const pills=[...document.querySelectorAll(".speed-pill")];
  const COUNTDOWN="COUNTDOWN",PLAYING="PLAYING",PAUSED="PAUSED",REFIRE_HOLD="REFIRE_HOLD",ENDED="ENDED";
  let state=COUNTDOWN,simTime=0,playbackSpeed=1;
  let countdownElapsed=0,holdElapsed=0,lastWall=null,dragging=false;
  function hideCount() { countdown.style.display="none"; countdown.textContent=""; }
  function showCount() {
    countdown.style.display="block";
    countdown.textContent=String(3-Math.floor(countdownElapsed));
  }
  function transition(next) {
    state=next;
    if(state!==COUNTDOWN)hideCount();
    const running=state===PLAYING||state===COUNTDOWN||state===REFIRE_HOLD;
    pauseIcon.style.display=running?"":"none";
    playIcon.style.display=running?"none":"";
    toggle.setAttribute("aria-label",running?"Pause":"Play");
    soundState(state===PLAYING&&!dragging);
  }
  toggle.addEventListener("click",()=>{
    lastWall=performance.now();
    if(state===PLAYING||state===COUNTDOWN||state===REFIRE_HOLD)transition(PAUSED);
    else {
      if(state===ENDED){simTime=0;scrubber.value="0";render(0);}
      transition(PLAYING);
    }
  });
  for(const pill of pills) pill.addEventListener("click",()=>{
    playbackSpeed=Number(pill.dataset.speed);
    for(const p of pills) {
      const active=p===pill;
      p.classList.toggle("is-active",active);
      p.setAttribute("aria-checked",String(active));
    }
  });
  scrubber.addEventListener("pointerdown",()=>{dragging=true;soundState(false);});
  function endDrag(){if(dragging){dragging=false;soundState(state===PLAYING);}}
  window.addEventListener("pointerup",endDrag);
  window.addEventListener("pointercancel",endDrag);
  scrubber.addEventListener("input",()=>{
    transition(PAUSED);
    simTime=parseFloat(scrubber.value);
    render(simTime);
  });
  byId("btn-refire").addEventListener("click",()=>{
    simTime=0;holdElapsed=0;countdownElapsed=0;scrubber.value="0";
    transition(REFIRE_HOLD);
    render(0);
    lastWall=performance.now();
  });
  function animate(now) {
    const dt=lastWall===null?0:clamp((now-lastWall)/1000,0,.1);
    lastWall=now;
    let advance=dt;
    if(state===COUNTDOWN){
      const prev=countdownElapsed;
      countdownElapsed+=dt;
      if(countdownElapsed>=3){advance=Math.max(0,dt-(3-prev));transition(PLAYING);}
      else showCount();
    } else if(state===REFIRE_HOLD){
      const prev=holdElapsed;
      holdElapsed+=dt;
      if(holdElapsed>=1){advance=Math.max(0,dt-(1-prev));transition(PLAYING);}
    }
    if(state===PLAYING){
      const before=simTime;
      simTime=Math.min(DURATION,simTime+advance*playbackSpeed);
      scrubber.value=simTime.toFixed(3);
      if(!dragging)advanceAudio(before,simTime);
      render(simTime);
      if(simTime>=DURATION)transition(ENDED);
    }
    requestAnimationFrame(animate);
  }
  window.addEventListener("resize",()=>{resize();render(simTime);});
  hideCount();
  resize();
  render(0);
  requestAnimationFrame(animate);

  REPORT
})();
