/bin/zsh -lc "printf '%s' 'const {chromium}=require(process.env.CDX_PW),{pathToFileURL}=require(\"node:url\");
const path=require(\"node:path\"),assert=require(\"node:assert/strict\");
(async()=>{
  const browser=await chromium.launch({executablePath:process.env.CDX_CHROME,
    args:[\"--enable-unsafe-swiftshader\",\"--use-angle=swiftshader\"]});
  try {
    const page=await browser.newPage({viewport:{width:1280,height:650},ignoreHTTPSErrors:true});
    await page.addInitScript(()=>{
      window.audioTest={starts:0,stops:0,compressors:0,resumes:0};
      for(const k of [\"OscillatorNode\",\"AudioBufferSourceNode\"]){
        for(const [method,count] of [[\"start\",\"starts\"],[\"stop\",\"stops\"]]){
          const old=window[k].prototype[method];
          window[k].prototype[method]=function(...args){audioTest[count]++;return old.apply(this,args);};
        }
      }
      const compress=BaseAudioContext.prototype.createDynamicsCompressor;
      BaseAudioContext.prototype.createDynamicsCompressor=function(...args){
        audioTest.compressors++;return compress.apply(this,args);
      };
      const resume=AudioContext.prototype.resume;
      AudioContext.prototype.resume=function(...args){
        audioTest.context=this;audioTest.resumes++;return resume.apply(this,args);
      };
    });
    await page.goto(pathToFileURL(path.resolve(\"index.html\")).href);
    await page.locator(\"#btn-toggle\").click();
    const read=()=>page.evaluate(()=>({starts:audioTest.starts,stops:audioTest.stops,
      compressors:audioTest.compressors,resumes:audioTest.resumes,state:audioTest.context.state}));
    const seek=t=>page.evaluate(t=>{
      const el=document.querySelector(\"#scrubber\");el.value=t;el.dispatchEvent(new Event(\"input\",{bubbles:true}));
    },t);
    await seek(.97);
    assert.equal((await read()).starts,0);
    await page.locator(\"#btn-toggle\").click();
    await page.waitForFunction(()=>audioTest.starts>0);
    await page.locator(\"#btn-toggle\").click();
    const paused=await read();
    assert(paused.stops>0);
    await seek(90.34);
    assert.equal((await read()).starts,paused.starts);
    await page.locator(\"#btn-toggle\").click();
    await page.waitForFunction(n=>audioTest.starts>n,paused.starts);
    const fallen=await read();
    assert.equal(fallen.state,\"running\");
    assert.equal(fallen.compressors,1);
    assert.equal(fallen.resumes,2);
    console.log(\"Verified autoplay-resume hooks, one compressor, event-driven wave and fall voices, and no voices triggered by scrubbing.\");
  } finally {await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
